    async function startLogin(provider) {
      clearLoginTimer();
      setMessage('\u6B63\u5728\u751F\u6210\u4E8C\u7EF4\u7801...');
      const result = await api('/website/api/login/start',{method:'POST',body:JSON.stringify({provider})});
      loginTask = { provider, taskId: result.taskId };
      showQr(result.qrImage, result.msg || '\u8BF7\u626B\u7801\u786E\u8BA4');
      if (isManualLoginProvider(provider)) {
        setMessage(manualLoginMessage(provider));
        return;
      }
      loginTimer = setInterval(() => pollLogin().catch(handleError), 1500);
      await pollLogin();
    }

    async function startBiliLogin() {
      clearLoginTimer();
      setMessage('\u6B63\u5728\u751F\u6210 Bili \u4E8C\u7EF4\u7801...');
      const result = await api('/website/api/bili/login/start',{method:'POST',body:'{}'});
      loginTask = { provider: 'bili', taskId: result.taskId };
      showQr(result.qrImage, result.msg || '\u8BF7\u4F7F\u7528\u54D4\u54E9\u54D4\u54E9 App \u626B\u7801\u786E\u8BA4');
      if (isManualLoginProvider('bili')) {
        setMessage(manualLoginMessage('bili'));
        return;
      }
      loginTimer = setInterval(() => pollLogin().catch(handleError), 1500);
      await pollLogin();
    }

    async function pollLogin() {
      if (!loginTask || loginPolling) return;
      loginPolling = true;
      try {
        const path = loginTask.provider === 'bili' ? '/website/api/bili/login/poll' : '/website/api/login/poll';
        const result = await api(path,{method:'POST',body:JSON.stringify(loginTask)});
        setMessage(result.msg || '\u7B49\u5F85\u626B\u7801\u786E\u8BA4');
        if (result.status === 'success') {
          clearLoginTimer();
          toast(result.msg || '\u767B\u5F55\u6210\u529F');
          await refresh();
        } else if (result.terminal || result.status === 'expired' || result.status === 'error') {
          clearLoginTimer();
          setMessage(result.msg || '\u767B\u5F55\u5931\u8D25', true);
        }
      } finally {
        loginPolling = false;
      }
    }

    async function cancelLogin() {
      if (loginTask) {
        const path = loginTask.provider === 'bili' ? '/website/api/bili/login/cancel' : '/website/api/login/cancel';
        await api(path,{method:'POST',body:JSON.stringify(loginTask)});
      }
      clearLoginTimer();
      setMessage('\u5DF2\u53D6\u6D88\u767B\u5F55');
    }

    function clearLoginTimer() {
      if (loginTimer) clearInterval(loginTimer);
      loginTimer = null;
      loginTask = null;
      loginPolling = false;
    }

    function showQr(src, text) {
      const box = $('qrBox');
      const img = $('qrImage');
      if (!box || !img) return;
      img.src = src || '';
      box.style.display = 'block';
      const cancel = $('cancelLoginBtn');
      if (cancel) cancel.onclick = () => cancelLogin().catch(handleError);
      const confirm = $('confirmLoginBtn');
      if (confirm) {
        confirm.style.display = isManualLoginProvider(loginTask && loginTask.provider) ? 'inline-flex' : 'none';
        confirm.onclick = () => pollLogin().catch(handleError);
      }
      setMessage(text || '\u8BF7\u626B\u7801\u786E\u8BA4');
    }

    function updateOrderSelect(selected) {
      const select = $('panOrderSelect');
      select.innerHTML = editingOrder.map((id,i) => '<option value="' + i + '">' + (i + 1) + '. ' + escapeHtml(nameOf(id)) + '</option>').join('');
      select.selectedIndex = Math.max(0, Math.min(selected || 0, editingOrder.length - 1));
      setMessage('\u9884\u89C8\u987A\u5E8F\uFF1A' + editingOrder.map(nameOf).join(' > '));
    }
    function moveOrder(step) {
      const select = $('panOrderSelect');
      const i = select.selectedIndex < 0 ? 0 : select.selectedIndex;
      const j = i + step;
      if (j < 0 || j >= editingOrder.length) return;
      const tmp = editingOrder[i];
      editingOrder[i] = editingOrder[j];
      editingOrder[j] = tmp;
      updateOrderSelect(j);
    }
    function textarea(id,label,value){return '<div><label for="' + id + '">' + label + '</label><textarea id="' + id + '">' + escapeHtml(value || '') + '</textarea></div>'}
    function input(id,label,value){return '<div><label for="' + id + '">' + label + '</label><input id="' + id + '" value="' + escapeHtml(value || '') + '"></div>'}
